@startuml
[*] --> HumanDriving

state HumanDriving {
    [*] --> InitialState : Power On
    InitialState : Initial State
    InitialState --> Autonomous : Front Distance > 10
    Autonomous --> HumanDriving : Human Steering Cmd or Brake Pressed
    HumanDriving --> FinalState : Power Off
    FinalState : Final State
}

state Autonomous {
    [*] --> InitialState : Enter Autonomous
    InitialState : Initial State
    InitialState --> FinalState : Exit Autonomous
}
@enduml

@startuml
[*] --> PumpControl

state PumpControl {
    [*] --> PumpState

    PumpState --> WaterState : Water Control
    PumpState --> MethaneState : Methane Control
    WaterState --> PumpState : Switch to Pump
    MethaneState --> PumpState : Switch to Pump
}
@enduml

@startuml
[*] --> PoweredOff

state Operate {
    [*] --> Idle
    Idle --> AcceleratingOrCruising : Accelerate Signal
    AcceleratingOrCruising --> Braking : Brake Signal
    Braking --> Idle : Stop Signal
}

PoweredOff --> Operate : start
Operate --> PoweredOff : keyOff
@enduml

@startuml
[*] --> DoorsClosing

state DoorsClosing {
  [*] --> DoorsClosing
}

DoorsClosing --> InMotion : Closed/SendDeparted

state InMotion {
  [*] --> Accelerating

  state Accelerating {
    entry/Accelerate
  }

  Accelerating --> Cruising : Reached Cruising/Cruise
  Accelerating --> Approaching : Approached/Decelerate

  state Cruising

  Cruising --> Approaching : Approached/Decelerate

  state Approaching {
    do/Send
  }
}

InMotion --> Stopping : Arrived/Stop, Send Arrived
InMotion --> EmergencyStopping : Obstacle Detected

state EmergencyStopping {
  entry/Emergency Stop
  do/Send Obstacle Detected
}

state Stopping
@enduml

@startuml
[*] --> DoorShut

state DoorShut {
    [*] --> DoorShut
    DoorShut --> DoorOpen : Door Opened
    DoorShut : Cancel
}

state DoorOpen {
    DoorOpen --> DoorOpenWithItem : Place Item Inside
    DoorOpen --> DoorShut : Close Door

    state DoorOpenWithItem {
        DoorOpenWithItem --> DoorOpen : Remove Item
        DoorOpenWithItem --> DoorShutWithItem : Close Door with Zero Time
        DoorOpenWithItem --> ReadytoCook : Enter Cooking Time
    }
}

state DoorShutWithItem {
    DoorShutWithItem --> DoorOpenWithItem : Open Door
    DoorShutWithItem --> ReadytoCook : Enter Cooking Time
}

state ReadytoCook {
    ReadytoCook --> DoorShutWithItem : Cancel
    ReadytoCook --> DoorOpenWithItem : Open Door
    ReadytoCook --> Cooking : Start
}

state Cooking {
    Cooking --> DoorOpenWithItem : Open Door
    Cooking --> DoorShutWithItem : Timer Expired
    Cooking --> ReadytoCook : Cancel
}
@enduml

@startuml
[*] --> InitialState

state InitialState {
    [*] --> DetectionState
    DetectionState : Possible Frontend Collision
    DetectionState : Rear-End Collision
    DetectionState : Collision With Pedestrian

    DetectionState --> BrakingControl : Frontend Collision Detected
    DetectionState --> SteeringControl : Rear-End Collision Detected
    DetectionState --> AlertSystem : Collision With Pedestrian Detected
}

state CollisionAvoidance {
    state BrakingControl {
        [*] --> ActivateABS
        ActivateABS --> ApplyBrakes : Immediate Action Required
        ApplyBrakes --> [*] : Collision Avoided
    }

    state SteeringControl {
        [*] --> ActivateESC
        ActivateESC --> SteerAway : Collision Imminent
        SteerAway --> [*] : Hazard Passed
    }

    state AlertSystem {
        [*] --> SendAlert
        SendAlert --> SoundAlarm
        SoundAlarm --> [*] : Obstacle Cleared
    }
}

CollisionAvoidance --> [*] : No Collision Risk

@enduml

@startuml
[*] --> TurnOn
state TurnOn {
  [*] --> ExecutionTime
  ExecutionTime --> fork1 : after 2s
}

fork1 --> AutoFocus
fork1 --> DetLight

state AutoFocus {
  [*] --> ExecutionTime
  ExecutionTime --> choice1 : after 1s
}

state DetLight {
  [*] --> ExecutionTime
  ExecutionTime --> choice2 : <<GaStep>>{prob=0.4}
}

fork1 --> choice3

choice1 --> Junction3 : memFull=true
choice3 --> ChargedFlash

state ChargedFlash {
  [*] --> ExecutionTime
  ExecutionTime --> Junction3 : after 2s
}

Junction3 --> Join2 : Charged=true

choice2 --> Join2
Join2 --> Fork2

Fork2 --> Junction2
Fork2 --> Flash

Flash --> Terminate

Junction2 --> TakePicture
TakePicture --> WriteMemory

state WriteMemory {
  [*] --> ExecutionTime
  ExecutionTime --> Junction1 : after 2s
}

Junction1 --> TurnOff

state TurnOff {
  [*] --> ExecutionTime
  ExecutionTime --> [*] : after 2s
}
@enduml

@startuml
[*] --> Off
Off --> Operate : start
state Operate {
[*] --> Idle
Idle --> AcceleratingOrCruising : accelerate
AcceleratingOrCruising --> Braking : brake
Braking --> Idle : stop
}
Operate --> Off : keyOff
@enduml

@startuml

DoorsClosing --> InMotion: Closed/SendDeparted

state InMotion {
[*] --> Accelerating : Entry/Accelerate
Accelerating --> Cruising : Reached Cruising/Cruise
Accelerating --> Approaching : Approached/Decelerate
Cruising --> Approaching : Approached/Decelerate

state Accelerating
state Cruising
state Approaching {
DuringApproaching: Nearing Destination
DuringApproaching --> Approaching: Send
}
}

InMotion --> Stopping: Arrived/Stop, SendArrived
InMotion --> EmergencyStopping: Obstacle Detected

state Stopping
state EmergencyStopping {
Entry: Emergency Stop
DuringEmergencyStopping: Obstacle Detected
}
@enduml

@startuml

[*] -> DoorShut

state DoorShut {
[*] -> State1
State1 -down-> State2 : Open Door
State1 --> State1 : Cancel
State2 -> DoorOpen: Close Door
}

state DoorOpen {
[*] -> State1
State1 -> DoorOpenWithItem : Place Item
DoorOpenWithItem --> State1 : Remove Item
}

state DoorOpenWithItem {
[*] -> State1
State1 --> DoorShutWithItem : Close Door/Zero Time
State1 --> ReadytoCook : Enter Time
}

state DoorShutWithItem {
[*] -> State1
State1 --> DoorOpenWithItem : Open Door
State1 --> ReadytoCook : Enter Time
}

state ReadytoCook {
[*] -> State1
State1 --> Cooking : Start
State1 --> DoorOpenWithItem : Open Door
State1 --> DoorShutWithItem : Cancel/Update Time
}

state Cooking {
[*] -> State1
State1 --> DoorOpenWithItem : Open Door/Stop Timer
State1 --> DoorShutWithItem : Timer Expired
State1 -> ReadytoCook : Cancel
}

@enduml

@startuml
[*] --> SearchMission : Start Mission

state SearchMission {
  [*] --> Area1
  Area1 --> Area2 : Finished Area1
  Area2 --> Area3 : Finished Area2
  Area3 -->[*] : Finished Area3
}

SearchMission --> FormationAdjust : Interception Detected

state FormationAdjust {
  [*] --> AdjustingFormation
  AdjustingFormation --> SearchMission : Finish Adjusting
}

SearchMission --> AttackState : Task Assignment Received

state AttackState {
  [*] --> Attacking
  Attacking --> SearchMission : Attack Finished / Decrease UAV swarm count
}
@enduml

@startuml
[*] --> TurnOn : 2 sec
state fork1
TurnOn --> fork1

fork1 --> AutoFocus : 1-2 sec
state AutoFocus {
    state choice1
    AutoFocus -down-> choice1 : memFull=true
}

fork1 --> DetLight : <1 sec
state DetLight {
    state choice2
    DetLight -down-> choice2 : <<GaStep>>{prob=0.4}
}

fork1 --> choice3
state choice3 {
    state ChargedFlash: 2-4 sec
    choice3 -down-> ChargedFlash
    ChargedFlash -down-> Junction3 : Charged=true
    choice3 -down-> Junction3
}

state Junction3 {
    state Join2
    Junction3 --> Join2
}
state Join2 {
    state Fork2
    Join2 --> Fork2
    state Join1
    choice2 --> Join1 when : sunny=true
    Join1 --> Junction2
}

state Flash {
    Fork2 --> Flash
    Flash --> Terminate
}

state Junction2 {
    state TakePicture
    Junction2 --> TakePicture
    TakePicture --> WriteMemory : 2-3 sec
}

state WriteMemory {
    state Junction1
    WriteMemory --> Junction1
}

state TurnOff
Junction1 --> TurnOff
TurnOff -left->[*]
@enduml

@startuml
[*] --> HumanDriving : Power On

state HumanDriving {
}

state Autonomous {
state Navigating
state Parking
[*] --> Navigating
Navigating --> Parking : Park Request
Parking --> Navigating : Parking Complete
}

HumanDriving --> Autonomous : front_distance > 10
Autonomous --> HumanDriving : Human Steering Cmd / Brake Pressed / [*]

[*] --> FinalState : Power Off
@enduml

@startuml
[*] --> TurnOn
state TurnOn {
state TurnOn {
[*] --> TurnOn
TurnOn --> fork1 : after 2s / minimum 2s
}
}

state fork1 {
[*] --> AutoFocus
[*] --> DetLight
}

state AutoFocus {
AutoFocus --> choice1 : after 2s / minimum 1s
}

state DetLight {
DetLight --> choice2 : after 1s / <<GaStep>>{prob=0.4}
}

fork1 --> choice3

choice3 --> ChargedFlash
state ChargedFlash {
ChargedFlash --> Junction3 : after 4s / minimum 2s
}

state Junction3 {
Junction3 --> Join2 : Charged=true
}

choice3 --> Junction3

choice2 --> Join2
state Join2 {
Join2 --> Fork2
}

Fork2 --> Junction2
Fork2 --> Flash

state Junction2 {
Junction2 --> TakePicture
}
Junction2 --> TakePicture
state TakePicture {
TakePicture --> WriteMemory
}

state WriteMemory {
WriteMemory --> Junction1 : after 3s / minimum 2s
}

state Junction1 {
Junction1 --> TurnOff
}

TurnOff --> [*]

Flash --> Terminate

state Terminate {
[*] --> Terminate
}

@enduml

@startuml
stm PumpControlSystem [Pump Control State Machine]

[*] --> PumpControl

state PumpControl {
[*] --> PumpState
PumpState --> WaterState : [Water Flow Detected]
PumpState --> MethaneState : [Methane Flow Detected]
WaterState --> PumpState : [Water Flow Completed]
MethaneState --> PumpState : [Methane Flow Completed]
}

@enduml

@startuml
stm MicrowaveStateMachine [Microwave State Machine]

[*] --> DoorShut

state DoorShut {
[*] --> DoorShutIdle
DoorShutIdle --> DoorShutIdle : Cancel
DoorShutIdle --> DoorOpen : Door Opened
}

state DoorOpen {
[*] --> DoorOpenIdle
DoorOpenIdle --> DoorOpenWithItem : Item Placed
DoorOpenWithItem --> DoorOpenIdle : Item Removed
DoorOpenWithItem --> DoorShutWithItem : Door Closed [zero time set]
DoorOpenWithItem --> ReadytoCook : Cooking Time Entered
}

state DoorShutWithItem {
[*] --> DoorShutWithItemIdle
DoorShutWithItemIdle --> DoorOpenWithItem : Door Opened
DoorShutWithItemIdle --> ReadytoCook : Cooking Time Entered
}

state ReadytoCook {
[*] --> ReadytoCookIdle
ReadytoCookIdle --> DoorShutWithItem : Cancel
ReadytoCookIdle --> DoorOpenWithItem : Door Opened
ReadytoCookIdle --> Cooking : Start
}

state Cooking {
[*] --> CookingIdle
CookingIdle --> DoorOpenWithItem : Door Opened
CookingIdle --> DoorShutWithItem : Timer Expired
CookingIdle --> ReadytoCook : Cancel
}

@enduml

@startuml
stm CollisionAvoidanceSystem [Collision Avoidance State Machine]

state "Frontend Collision Avoidance" as Frontend {
[*] --> Idle
Idle --> Braking : Collision Detected
Braking --> Clamping : Brake Applied
Clamping --> Idle : Collision Avoided
}

state "Rear-End Collision Avoidance" as RearEnd {
[*] --> Idle
Idle --> Braking : Collision Detected
Braking --> Clamping : Brake Applied
Clamping --> Idle : Collision Avoided
}

state "Pedestrian Collision Avoidance" as Pedestrian {
[*] --> Idle
Idle --> Braking : Collision Detected
Braking --> Clamping : Brake Applied
Clamping --> Idle : Collision Avoided
}

Frontend --> [*] : Collision Avoided
RearEnd --> [*] : Collision Avoided
Pedestrian --> [*] : Collision Avoided

@enduml

@startuml

[*] --> HumanDrivingMode : Power On

state HumanDrivingMode {
}

state AutonomousMode {
[*] --> SubState1
SubState1 --> SubState2
SubState2 --> SubState3
SubState3 --> [*]
}

HumanDrivingMode --> AutonomousMode : [front_distance > 10]

AutonomousMode --> HumanDrivingMode : human steering cmd\nor brake pressed\nor in (auto final)

HumanDrivingMode --> [*] : Power Off
AutonomousMode --> [*] : Power Off

@enduml

@startuml

[*] --> Off
Off --> Operate : start

state Operate {
[*] --> Idle
Idle --> Accelerating_or_Cruising : accelerate
Accelerating_or_Cruising --> Braking : brake
Braking --> Idle : stop
Accelerating_or_Cruising --> Idle : stop
}

Operate --> Off : keyOff

@enduml

@startuml

[*] --> PumpControl

state PumpControl {
[*] --> PumpState
PumpState : Pump activated or controlled
WaterState : Water flow control/monitoring
MethaneState : Methane flow control/monitoring

PumpState --> WaterState
PumpState --> MethaneState
WaterState --> PumpState
MethaneState --> PumpState
}

@enduml

@startuml

state "Collision Avoidance" as CA {
state "Frontend Collision" as FC {
[*] --> FCIdle
FCIdle --> FCActive : Frontend collision detected
FCActive --> FCIdle : Collision avoided
}

state "Rear-end Collision" as RC {
[*] --> RCIdle
RCIdle --> RCActive : Rear-end collision detected
RCActive --> RCIdle : Collision avoided
}

state "Pedestrian Collision" as PC {
[*] --> PCIdle
PCIdle --> PCActive : Pedestrian collision detected
PCActive --> PCIdle : Collision avoided
}
}

[*] --> CA : Possible collision detected

@enduml

@startuml

state TurnOn {
state "TurnOn" as TurnOn_state
}
TurnOn_state : {max=2s, min=2s}

[*] --> TurnOn_state
TurnOn_state --> fork1

fork fork1
fork1 --> AutoFocus
fork1 --> DetLight
fork1 --> choice3

state AutoFocus {
state "AutoFocus" as AutoFocus_state
}
AutoFocus_state : {max=2s, min=1s}

AutoFocus_state --> choice1 : [memFull=true]

state DetLight {
state "DetLight" as DetLight_state
}
DetLight_state : {max=1s, min=0s}

DetLight_state --> choice2 : <<GaStep>>{prob=0.4}

state ChargedFlash {
state "ChargedFlash" as ChargedFlash_state
}
ChargedFlash_state : {max=4s, min=2s}

choice3 --> ChargedFlash_state
ChargedFlash_state --> Junction3 : [Charged=true]
choice3 --> Junction3

Junction3 --> Join2

choice2 --> Join2
choice2 --> Join1 : [sunny=true]

Join1 --> Junction2

Junction2 --> TakePicture
TakePicture --> WriteMemory
state WriteMemory {
state "WriteMemory" as WriteMemory_state
}
WriteMemory_state : {max=3s, min=2s}

WriteMemory_state --> Junction1
Junction1 --> TurnOff
TurnOff --> [*]

state Join2 {
fork2 --> Junction2
fork2 --> Flash
}

Flash --> Terminate

@enduml
